package dev.zomboid.decor;
import java.util.*;
public final class Footprint {
 public static Object PART;
 public static final Set<String> IDS=java.util.concurrent.ConcurrentHashMap.newKeySet();
 public static void spec(Object spec){if(!"Block".equals(R.get(spec,"type")))return;Object shapes=R.get(spec,"shapes");if(shapes instanceof Map<?,?> map)for(Object value:map.values())for(double[] box:(double[][])value)if(box[0]<-1e-7||box[1]<-1e-7||box[2]<-1e-7||box[3]>16.0000001||box[4]>16.0000001||box[5]>16.0000001){IDS.add(R.get(spec,"id").toString());return;}}
 static final ThreadLocal<Boolean> CLEANING=ThreadLocal.withInitial(()->false);
 public record Cell(int x,int y,int z){}
 public static Set<Cell> cells(List<?> boxes){Set<Cell> cells=new LinkedHashSet<>();for(Object b:boxes){int minX=(int)Math.floor(R.num(R.get(b,"minX"))+1e-7),minY=(int)Math.floor(R.num(R.get(b,"minY"))+1e-7),minZ=(int)Math.floor(R.num(R.get(b,"minZ"))+1e-7);int maxX=(int)Math.ceil(R.num(R.get(b,"maxX"))-1e-7),maxY=(int)Math.ceil(R.num(R.get(b,"maxY"))-1e-7),maxZ=(int)Math.ceil(R.num(R.get(b,"maxZ"))-1e-7);if((long)(maxX-minX)*(maxY-minY)*(maxZ-minZ)>64)throw new IllegalStateException("Oversized furniture");for(int x=minX;x<maxX;x++)for(int y=minY;y<maxY;y++)for(int z=minZ;z<maxZ;z++)if(x!=0||y!=0||z!=0)cells.add(new Cell(x,y,z));}return cells;}
 static Set<Cell> cells(Object state,Object world,Object pos){return cells((List<?>)R.call(R.call(state,"getShape",world,pos),"toAabbs"));}
 static Object pos(Object p,Cell c){return R.call(p,"offset",c.x,c.y,c.z);}
 static boolean selected(Object state){return IDS.contains(Storage.id(state));}
 static boolean owned(Object world,Object p,Object root,String owner){Object be=R.call(world,"getBlockEntity",p);return be!=null&&be.getClass().getName().endsWith("AcrateBlockEntity")&&R.yes(R.get(be,"ddPart"))&&R.lng(R.get(be,"ddRoot"))==R.lng(R.call(root,"asLong"))&&owner.equals(R.get(be,"ddOwner"));}
 public static Object root(Object be){if(!be.getClass().getName().endsWith("AcrateBlockEntity")||!R.yes(R.get(be,"ddPart")))return null;Object world=R.call(be,"getLevel");if(world==null)return null;Object p=R.call(R.type("net.minecraft.core.BlockPos"),"of",R.get(be,"ddRoot"));if(!R.yes(R.call(world,"hasChunkAt",p)))return null;return Storage.id(R.call(world,"getBlockState",p)).equals(R.get(be,"ddOwner"))?p:null;}
 public static Object validate(Object context,Object state){if(state==null||!selected(state))return state;Object world=R.call(context,"getLevel"),p=R.call(context,"getClickedPos");for(Cell c:cells(state,world,p)){Object q=pos(p,c);if(!R.yes(R.call(world,"hasChunkAt",q))||R.call(world,"getBlockEntity",q)!=null||!R.yes(R.call(R.call(world,"getBlockState",q),"canBeReplaced",context)))return null;}return state;}
 public static void ensure(Object world,Object p,Object state){if(PART==null||!selected(state)||R.yes(R.call(world,"isClientSide")))return;String owner=Storage.id(state);Set<Cell> cs=cells(state,world,p);for(Cell c:cs){Object q=pos(p,c);if(!R.yes(R.call(world,"hasChunkAt",q)))return;if(owned(world,q,p,owner))continue;Object s=R.call(world,"getBlockState",q);if(R.call(world,"getBlockEntity",q)!=null||!R.yes(R.call(s,"canBeReplaced")))return;}for(Cell c:cs){Object q=pos(p,c);if(owned(world,q,p,owner))continue;R.call(world,"setBlock",q,R.call(PART,"defaultBlockState"),3);Object be=R.call(world,"getBlockEntity",q);if(be==null)throw new IllegalStateException("Missing furniture part entity");R.set(be,"ddPart",true);R.set(be,"ddRoot",R.call(p,"asLong"));R.set(be,"ddOwner",owner);R.call(be,"setChanged");Object s=R.call(world,"getBlockState",q);R.call(world,"sendBlockUpdated",q,s,s,3);}}
 public static Object shape(Object state,Object world,Object p,Object context,boolean collision,Object original){if(!Storage.id(state).equals("interaction_part"))return original;Object be=R.call(world,"getBlockEntity",p),root=be==null?null:root(be);if(root==null)return R.call(R.type("net.minecraft.world.phys.shapes.Shapes"),"empty");Object s=R.call(world,"getBlockState",root),shape=R.call(s,collision?"getCollisionShape":"getShape",world,root,context);Object moved=R.call(shape,"move",R.coord(root,"X")-R.coord(p,"X"),R.coord(root,"Y")-R.coord(p,"Y"),R.coord(root,"Z")-R.coord(p,"Z"));return R.call(R.type("net.minecraft.world.phys.shapes.Shapes"),"join",moved,R.call(R.type("net.minecraft.world.phys.shapes.Shapes"),"block"),R.get(R.type("net.minecraft.world.phys.shapes.BooleanOp"),"AND"));}
 public static boolean remove(Object state,Object world,Object p){boolean part=Storage.id(state).equals("interaction_part");if(CLEANING.get()||R.yes(R.call(world,"isClientSide")))return part;CLEANING.set(true);try{if(part){Object be=R.call(world,"getBlockEntity",p),root=be==null?null:root(be);if(root!=null){Object s=R.call(world,"getBlockState",root);for(Cell c:cells(s,world,root)){Object q=pos(root,c);if(!q.equals(p)&&owned(world,q,root,Storage.id(s)))R.call(world,"removeBlock",q,false);}R.call(world,"destroyBlock",root,true);}}else if(selected(state)){for(Cell c:cells(state,world,p)){Object q=pos(p,c);if(R.yes(R.call(world,"hasChunkAt",q))&&owned(world,q,p,Storage.id(state)))R.call(world,"removeBlock",q,false);}}return part;}finally{CLEANING.set(false);}}
 public static float progress(Object state,Object player,Object world,Object p,float original){if(!Storage.id(state).equals("interaction_part"))return original;Object be=R.call(world,"getBlockEntity",p),root=be==null?null:root(be);return root==null?original:((Number)R.call(R.call(world,"getBlockState",root),"getDestroyProgress",player,world,root)).floatValue();}
 public static void breaking(Object e){Object world=R.call(e,"getLevel"),p=R.call(e,"getPos"),s=R.call(e,"getState");if(!Storage.id(s).equals("interaction_part"))return;Object be=R.call(world,"getBlockEntity",p),root=be==null?null:root(be);if(root==null)return;R.call(e,"setCanceled",true);Object player=R.call(e,"getPlayer");R.call(R.get(player,"gameMode"),"destroyBlock",root);}
 public static void orphan(Object world,Object p){Object be=R.call(world,"getBlockEntity",p);if(be==null)return;if(!R.yes(R.get(be,"ddPart"))){R.call(world,"removeBlock",p,false);return;}Object root=R.call(R.type("net.minecraft.core.BlockPos"),"of",R.get(be,"ddRoot"));if(R.yes(R.call(world,"hasChunkAt",root))&&!Storage.id(R.call(world,"getBlockState",root)).equals(R.get(be,"ddOwner")))R.call(world,"removeBlock",p,false);}
 public static void tick(Object e){Object player=R.call(e,"getEntity"),world=R.call(player,"level");if(R.yes(R.call(world,"isClientSide"))||R.lng(R.call(world,"getGameTime"))%40!=0)return;Object center=R.call(player,"blockPosition");for(int x=-5;x<=5;x++)for(int z=-5;z<=5;z++)for(int y=-3;y<=3;y++){Object p=R.call(center,"offset",x,y,z);if(!R.yes(R.call(world,"hasChunkAt",p)))continue;Object s=R.call(world,"getBlockState",p);if(selected(s))ensure(world,p,s);else if(Storage.id(s).equals("interaction_part"))orphan(world,p);}}
}
